CREATE TYPE "Role" AS ENUM ('OPERATOR','OWNER'); CREATE TYPE "Mode" AS ENUM ('TWILIO_FORWARD','CONDITIONAL_FORWARD'); CREATE TYPE "SetupStatus" AS ENUM ('INCOMPLETE','READY','TESTED','ACTIVE','SUSPENDED'); CREATE TYPE "CallOutcome" AS ENUM ('ANSWERED','NO_ANSWER','BUSY','FAILED','FORWARDED','UNKNOWN'); CREATE TYPE "EnquiryStatus" AS ENUM ('NEW','CONTACTED','BOOKED','CLOSED','INVALID'); CREATE TYPE "SmsDirection" AS ENUM ('OUTBOUND','INBOUND'); CREATE TYPE "SmsStatus" AS ENUM ('QUEUED','SENT','DELIVERED','FAILED','UNDELIVERED','RECEIVED','SUPPRESSED');
CREATE TABLE "Business" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"trade" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"mode" "Mode" NOT NULL,"callbackPhone" TEXT,"template" TEXT NOT NULL,"cooldownMinutes" INTEGER NOT NULL DEFAULT 60,"automationEnabled" BOOLEAN NOT NULL DEFAULT false,"setupStatus" "SetupStatus" NOT NULL DEFAULT 'INCOMPLETE',"demo" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT UNIQUE NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"businessId" TEXT REFERENCES "Business"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PhoneNumber" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE CASCADE,"number" TEXT UNIQUE NOT NULL,"purpose" TEXT NOT NULL,"voice" BOOLEAN NOT NULL DEFAULT false,"sms" BOOLEAN NOT NULL DEFAULT false,"twoWay" BOOLEAN NOT NULL DEFAULT false,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "IncomingCall" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id"),"sid" TEXT UNIQUE NOT NULL,"from" TEXT,"to" TEXT NOT NULL,"outcome" "CallOutcome" NOT NULL DEFAULT 'UNKNOWN',"simulated" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Enquiry" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id"),"caller" TEXT,"callId" TEXT UNIQUE REFERENCES "IncomingCall"("id") ON DELETE SET NULL,"status" "EnquiryStatus" NOT NULL DEFAULT 'NEW',"replyReceived" BOOLEAN NOT NULL DEFAULT false,"notes" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SmsMessage" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"enquiryId" TEXT REFERENCES "Enquiry"("id") ON DELETE SET NULL,"sid" TEXT UNIQUE,"direction" "SmsDirection" NOT NULL,"from" TEXT NOT NULL,"to" TEXT NOT NULL,"body" TEXT NOT NULL,"status" "SmsStatus" NOT NULL,"simulated" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Suppression" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id"),"phone" TEXT NOT NULL,"reason" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","phone"));
CREATE TABLE "WebhookEvent" ("id" TEXT PRIMARY KEY,"businessId" TEXT REFERENCES "Business"("id") ON DELETE SET NULL,"externalId" TEXT UNIQUE NOT NULL,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OutboxJob" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id"),"enquiryId" TEXT,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SetupTest" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id"),"type" TEXT NOT NULL,"passed" BOOLEAN NOT NULL,"details" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY,"businessId" TEXT REFERENCES "Business"("id") ON DELETE SET NULL,"actorId" TEXT,"action" TEXT NOT NULL,"details" JSONB);
